  const touchStart=useRef({x:0,y:0});const sessionStart=useRef<number|null>(null);const pendingLocator=useRef<string|null>(null);const selectionGuard=useRef(0);const progressTimer=useRef<number|null>(null);const pendingProgress=useRef<{bookId:string;location:ReaderLocation}|null>(null);const booksRef=useRef<Book[]>([]);
