    if(window.location.hostname.endsWith("pages.dev"))fetch("/api/library",{headers:{"x-papery-device":getDeviceId()}}).then(r=>r.ok?r.json():null).then(data=>{if(data?.sessions&&!localSessions.length)setSessions(data.sessions.map((item:ReadingSession,index:number)=>({...item,id:item.id||`remote-${item.started_at}-${index}`})));}).catch(()=>undefined);
