    const next:Book[]=records.map((record,index)=>({id:record.id,title:record.title,author:record.author,progress:record.progress,type:record.format,color:coverColors[index%coverColors.length],category:record.category,last:"已同步",source:booksRef.current.find(book=>book.id===record.id)?.source||URL.createObjectURL(record.blob),blob:record.blob,coverDataUrl:record.coverDataUrl,currentLocation:record.currentLocation}));
